Ah, this works well it seems, thanks! Thanks also for doing the legwork to try the model yourself, especially since I didn't post the relevant R code. For others, here's the R code:

library(lavaan)
data(HolzingerSwineford1939)
# a visual factor measured by 3 variables: x1, x2 and x3
# a textual factor measured by 3 variables: x4, x5 and x6
# a speed factor measured by 3 variables: x7, x8 and x9

library(tidyverse)
library(rstan)

HolzingerSwineford1939 %>%
select(
x1,x2,x3,x4,x5,x6,x7,x8,x9
) -> dat

cfa = rstan::stan_model('cfa.stan')
post = rstan::sampling(
object = cfa
, data = list(
N = nrow(dat)
, K = ncol(dat)
, Y = scale(dat)
)
, seed = 1
, cores = 4
, chains = 4
, iter = 2e4
)

